import numpy as np

K = np.array([[1000, 0, 960], [0, 1000, 540], [0, 0, 1.0]])   # 초점거리 1000px, 1920x1080
R = np.array([[0, -1, 0], [0, 0, -1], [1, 0, 0.0]])             # 자차(x앞 y왼 z위) -> 카메라(x오른 y아래 z앞)
t = np.array([0, 1.5, -1.0])                                      # 카메라: 앞 1m, 높이 1.5m


def to_pixel(p_ego):
    p_cam = R @ p_ego + t
    if p_cam[2] <= 0:
        return None                   # 카메라 뒤
    uv = K @ (p_cam / p_cam[2])
    return round(float(uv[0]), 1), round(float(uv[1]), 1), round(float(p_cam[2]), 1)


for p in [(20, 0, 0), (20, 2, 0), (40, 2, 0), (-5, 0, 0)]:
    print(p, to_pixel(np.array(p, float)))
